import{state}from"./state.js";import{refreshFromServerAndRender}from"./main-init.js";import{showToast}from"./utils.js";let socket=null,reconnectTimer=null;async function fetchWebSocketToken(){try{const e=await fetch("/api/ws-token",{credentials:"same-origin"});if(!e.ok)throw new Error(`Token fetch failed with status ${e.status}`);return(await e.json()).token}catch(e){return console.error("WS token fetch failed:",e),null}}export async function initializeWebSocket(){if(socket)return;const e=await fetchWebSocketToken(),t="https:"===window.location.protocol?"wss:":"ws:",o=e?`?token=${encodeURIComponent(e)}`:"",n=`${t}//${window.location.host}/ws${o}`;try{socket=new WebSocket(n),socket.onopen=()=>{reconnectTimer&&(clearTimeout(reconnectTimer),reconnectTimer=null)},socket.onmessage=e=>{try{handleWSMessage(JSON.parse(e.data))}catch(e){console.error("Failed to parse WS message:",e)}},socket.onclose=()=>{socket=null,reconnectTimer||(reconnectTimer=setTimeout(initializeWebSocket,5e3))},socket.onerror=e=>{console.error("WS error:",e),socket.close()}}catch(e){console.error("Failed to initialize WS:",e)}}function getPendingRequestsCount(){return(state.requests||[]).filter(e=>"pending"===e.status).length}function showChildUpdateForAdmin(e){e>0?showToast(`Новая заявка: +${e}`,"success"):showToast("Данные обновлены ребенком","info")}async function handleDataUpdatedMessage(e){const t=getPendingRequestsCount();await refreshFromServerAndRender(!1);const o=getPendingRequestsCount()-t;"admin"!==e.by||"child"!==state.role?"child"===e.by&&"admin"===state.role&&showChildUpdateForAdmin(o):showToast("Данные обновлены родителем","info")}async function handleWSMessage(e){const{type:t,data:o}=e;switch(t){case"DATA_UPDATED":await handleDataUpdatedMessage(o);break;case"CHILD_UPDATED":await refreshFromServerAndRender(!1);break;case"CHILD_DELETED":"child"===state.role&&state.childId===o.childId?window.location.reload():await refreshFromServerAndRender(!1)}}